gaI7(){return"\u0642\u0628\u0644 \u0627\u0644\u0645\u0628\u0627\u0631\u0627\u0629"},
gaIe(){return"\u0627\u0644\u0642\u0627\u0639\u0629 \u0645\u0641\u062a\u0648\u062d\u0629"},
